export const APT_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/apt-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getAptStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(APT_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
